#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <pthread.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_SESSIONS 1000
#define SESSION_TIMEOUT 1800
#define TOKEN_BYTES 32
#define PORT 8080
#define BUFFER_SIZE 8192

typedef struct {
    char token[TOKEN_BYTES * 2 + 1];
    char user_id[64];
    time_t created_at;
    time_t expires_at;
    char ip_address[INET_ADDRSTRLEN];
    int active;
} Session;

typedef struct {
    Session sessions[MAX_SESSIONS];
    pthread_mutex_t mutex;
    int count;
} SessionStore;

SessionStore store;

void init_store() {
    memset(&store, 0, sizeof(store));
    pthread_mutex_init(&store.mutex, NULL);
    store.count = 0;
}

int generate_secure_token(char *output, size_t len) {
    unsigned char buffer[TOKEN_BYTES];
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;
    ssize_t n = read(fd, buffer, TOKEN_BYTES);
    close(fd);
    if (n != TOKEN_BYTES) return -1;

    for (int i = 0; i < TOKEN_BYTES; i++) {
        sprintf(output + (i * 2), "%02x", buffer[i]);
    }
    output[TOKEN_BYTES * 2] = '\0';
    return 0;
}

int constant_time_compare(const char *a, const char *b) {
    unsigned char result = 0;
    size_t len = strlen(a);
    if (strlen(b) != len) return 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

Session* create_session(const char *user_id, const char *ip_address) {
    pthread_mutex_lock(&store.mutex);

    if (store.count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&store.mutex);
        return NULL;
    }

    Session *s = &store.sessions[store.count];
    if (generate_secure_token(s->token, sizeof(s->token)) != 0) {
        pthread_mutex_unlock(&store.mutex);
        return NULL;
    }

    strncpy(s->user_id, user_id, sizeof(s->user_id) - 1);
    s->user_id[sizeof(s->user_id) - 1] = '\0';
    strncpy(s->ip_address, ip_address, sizeof(s->ip_address) - 1);
    s->ip_address[sizeof(s->ip_address) - 1] = '\0';

    s->created_at = time(NULL);
    s->expires_at = s->created_at + SESSION_TIMEOUT;
    s->active = 1;

    store.count++;
    pthread_mutex_unlock(&store.mutex);
    return s;
}

Session* find_session(const char *token) {
    pthread_mutex_lock(&store.mutex);
    Session *found = NULL;

    for (int i = 0; i < store.count; i++) {
        if (store.sessions[i].active &&
            constant_time_compare(store.sessions[i].token, token)) {
            if (time(NULL) > store.sessions[i].expires_at) {
                store.sessions[i].active = 0;
            } else {
                found = &store.sessions[i];
            }
            break;
        }
    }

    pthread_mutex_unlock(&store.mutex);
    return found;
}

int destroy_session(const char *token) {
    pthread_mutex_lock(&store.mutex);
    int result = 0;

    for (int i = 0; i < store.count; i++) {
        if (store.sessions[i].active &&
            constant_time_compare(store.sessions[i].token, token)) {
            store.sessions[i].active = 0;
            result = 1;
            break;
        }
    }

    pthread_mutex_unlock(&store.mutex);
    return result;
}

void cleanup_expired_sessions() {
    pthread_mutex_lock(&store.mutex);
    time_t now = time(NULL);

    for (int i = 0; i < store.count; i++) {
        if (store.sessions[i].active && now > store.sessions[i].expires_at) {
            store.sessions[i].active = 0;
        }
    }

    pthread_mutex_unlock(&store.mutex);
}

