    char *uid = strstr(body, "user_id=");
    if (uid) {
        uid += 8;
        int i = 0;
        while (*uid && *uid != '&' && i < 63) {
            user_id[i++] = *uid++;
        }
        user_id[i] = '\0';
    }

    Session *s = create_session(user_id, ip);
    if (!s) {
        send_response(client_fd, 500, "Internal Server Error",
                     "text/html", "<h1>Server Error</h1>", NULL);
        return;
