        "<html><body>"
        "<h1>Login Successful</h1>"
        "<p>Session created. <a href=\"/protected\">Access Protected Page</a></p>"
        "<p><a href=\"/logout\">Logout</a></p>"
        "</body></html>";

    send_response(client_fd, 200, "OK", "text/html", response_body, cookie);
