    const char *response_body =
        "<html><body>"
        "<h1>Logged Out</h1>"
        "<p>Session terminated. <a href=\"/\">Home</a></p>"
        "</body></html>";

    char clear_cookie[256];
    snprintf(clear_cookie, sizeof(clear_cookie),
             "session_id=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0");

    send_response(client_fd, 200, "OK", "text/html", response_body, clear_cookie);
}

void handle_protected(int client_fd, const char *cookie_header) {
    char token[TOKEN_BYTES * 2 + 1] = {0};
    char *sid = strstr(cookie_header, "session_id=");
    if (sid) {
        sid += 11;
        int i = 0;
        while (*sid && *sid != ';' && i < TOKEN_BYTES * 2) {
            token[i++] = *sid++;
        }
        token[i] = '\0';
    }

    Session *s = find_session(token);
    if (!s) {
        send_response(client_fd, 401, "Unauthorized", "text/html",
                     "<h1>Unauthorized</h1><p><a href=\"/\">Login</a></p>", NULL);
        return;
    }

    char body[512];
    snprintf(body, sizeof(body),
        "<html><body>"
        "<h1>Protected Content</h1>"
        "<p>Welcome, %s!</p>"
        "<p>Session expires at: %ld</p>"
        "<p><a href=\"/logout\">Logout</a></p>"
        "</body></html>",
        s->user_id, (long)s->expires_at);

    send_response(client_fd, 200, "OK", "text/html", body, NULL);
}

void handle_home(int client_fd) {
    const char *body =
        "<html><body>"
        "<h1>Session Management Demo</h1>"
        "<form method=\"POST\" action=\"/login\">"
        "<input type=\"text\" name=\"user_id\" placeholder=\"User ID\" required>"
        "<button type=\"submit\">Login</button>"
        "</form>"
        "<p><a href=\"/protected\">Protected Page</a></p>"
        "</body></html>";

    send_response(client_fd, 200, "OK", "text/html", body, NULL);
}

void handle_request(int client_fd, const char *request, const char *ip) {
    char method[16] = {0};
    char path[256] = {0};
    char version[16] = {0};

    sscanf(request, "%15s %255s %15s", method, path, version);

    char *cookie_header = strstr(request, "Cookie:");
    char cookie_value[512] = {0};
    if (cookie_header) {
        cookie_header += 7;
        while (*cookie_header == ' ') cookie_header++;
        char *end = strstr(cookie_header, "\r\n");
        if (end) {
            size_t len = end - cookie_header;
            if (len >= sizeof(cookie_value)) len = sizeof(cookie_value) - 1;
            strncpy(cookie_value, cookie_header, len);
            cookie_value[len] = '\0';
        }
    }

    char *body = strstr(request, "\r\n\r\n");
    if (body) body += 4;

    if (strcmp(method, "POST") == 0 && strcmp(path, "/login") == 0) {
        handle_login(client_fd, body ? body : "", ip);
    } else if (strcmp(method, "GET") == 0 && strcmp(path, "/logout") == 0) {
        handle_logout(client_fd, cookie_value);
    } else if (strcmp(method, "GET") == 0 && strcmp(path, "/protected") == 0) {
        handle_protected(client_fd, cookie_value);
    } else if (strcmp(method, "GET") == 0 && strcmp(path, "/") == 0) {
        handle_home(client_fd);
    } else {
        send_response(client_fd, 404, "Not Found", "text/html",
                     "<h1>404 Not Found</h1>", NULL);
    }
}

void* client_handler(void *arg) {
    int client_fd = *(int*)arg;
    free(arg);

    char buffer[BUFFER_SIZE] = {0};
    ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);

    if (bytes_read > 0) {
        struct sockaddr_in addr;
        socklen_t addr_len = sizeof(addr);
        getpeername(client_fd, (struct sockaddr*)&addr, &addr_len);
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &addr.sin_addr, ip, sizeof(ip));

        handle_request(client_fd, buffer, ip);
    }

    close(client_fd);
    return NULL;
}

int main() {
    init_store();

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        perror("bind");
        return 1;
    }

    if (listen(server_fd, 10) < 0) {
        perror("listen");
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int *client_fd = malloc(sizeof(int));
        *client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);

        if (*client_fd < 0) {
            free(client_fd);
            continue;
        }

        pthread_t thread;
        pthread_create(&thread, NULL, client_handler, client_fd);
        pthread_detach(thread);

        cleanup_expired_sessions();
    }

    close(server_fd);
    return 0;
}
